\title{A Dimension-Free Spectral Bound for the Signless Laplacian\\ of Pure Simplicial Complexes}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
We develop a dimension-free analytic engine for bounding the signless Laplacian spectral radius $q_{r-1}(K)$ of a pure $r$-dimensional simplicial complex $K$. Modeling the facet--ridge incidence abstractly, we express the signless Laplacian quadratic form as a manifest sum of squares over facets, prove that it coincides with the matrix form $x^{\T}(BB^{\T})x$ of the unsigned incidence Laplacian, and derive --- via a single per-facet Cauchy--Schwarz inequality followed by a double-counting identity --- the bound $q_{r-1}(K) \le (r+1)\Delta$, where $r+1$ is the constant facet size of a pure $r$-complex and $\Delta$ is the maximum ridge degree. The bound is sharp: a single $r$-simplex attains $q_{r-1} = r+1$ with the all-ones eigenvector. Specializing to $r=1$ recovers the classical graph bound $q(G) \le 2\Delta(G)$, obtained rigorously by modeling edges as two-element facets; a catalog bridge confirms that the $1$-skeleton of the clique complex of a graph $G$ equals $G$. These results constitute the spectral half of a conjecture relating link-homology vanishing to the signless Laplacian spectral radius, reducing the conjecture to a purely combinatorial degree estimate.
\end{abstract}

\section{Introduction}

\subsection{Background}
Spectral graph theory studies a graph through eigenvalues of associated matrices. The \emph{signless Laplacian} $Q = D + A$, the sum of the degree matrix $D$ and the adjacency matrix $A$, is positive semidefinite, and its largest eigenvalue $q(G)$ (the signless Laplacian spectral radius) governs spreading rates and structural robustness. A foundational inequality is
\[
q(G) \le 2\,\Delta(G),
\]
where $\Delta(G)$ is the maximum degree. Higher-order applications --- topological data analysis, discrete geometry, lattice physics --- demand the analogue for \emph{pure $r$-dimensional simplicial complexes}, objects built entirely from $r$-simplices, carrying a signless Laplacian on their \emph{ridges} (the $(r-1)$-faces) defined through incidence with their \emph{facets} (the $r$-faces).

\subsection{The conjecture}
\begin{conjecture}[link-homology spectral bound]
Let $K$ be a pure $r$-dimensional complex on $n$ vertices and $t \ge 1$ an integer. If for every face $\sigma$ of dimension $r-t$ the reduced real homology of the link vanishes in degree $t$, $\rH_t(\lk(\sigma);\R) = 0$, then
\[
q_{r-1}(K) \le t\,n - (t-1)(r+1).
\]
Moreover, if $K$ is $r$-down-path-connected and $n$ is sufficiently large, equality holds iff $K$ is the join of an $(r+1-t)$-simplex with the $(t-1)$-skeleton of a simplex on $n-r-1+t$ vertices.
\end{conjecture}

\subsection{Contribution}
We establish the \emph{spectral half} of the conjecture in full generality: a dimension-free bound $q_{r-1}(K) \le (r+1)\Delta$. Combined with the observation that the homology hypothesis caps ridge degrees, this collapses the inequality to a single combinatorial estimate. We prove the bound sharp on the simplex and connect the theory to the classical graph case and a clique-complex catalog. Prose theorems carry, in parentheses, the names of the corresponding machine-checked lemmas.

\section{The incidence model}

\begin{definition}[incidence structure]
Let $R$ be a finite set of \emph{ridges} and $F$ a finite index set of \emph{facets}. The incidence is a map $\facet : F \to \mathcal{P}(R)$, $f \mapsto \facet(f) \subseteq R$. For a pure $r$-complex, $|\facet(f)| = r+1$ for all $f$.
\end{definition}

\begin{definition}[ridge degree]
$\deg(\rho) := \bigl|\{ f \in F : \rho \in \facet(f) \}\bigr|.$
\end{definition}

\begin{definition}[signless Laplacian matrix]
$Q = BB^{\T}$, where $B \in \{0,1\}^{R\times F}$, $B_{\rho f} = 1$ iff $\rho \in \facet(f)$. Entrywise,
\[
Q_{\rho\rho'} = \bigl|\{ f \in F : \rho \in \facet(f) \text{ and } \rho' \in \facet(f) \}\bigr|, \qquad Q_{\rho\rho} = \deg(\rho).
\]
\end{definition}

\begin{definition}[quadratic form]
For $x \in \R^{R}$,
\[
\slQuad(x) = \sum_{f \in F}\Bigl(\sum_{\rho \in \facet(f)} x_\rho\Bigr)^{2}.
\]
\end{definition}

\begin{definition}[spectral radius]
\[
q_{r-1}(K) := \specRad = \sup_{\substack{x \in \R^R \\ \sum_\rho x_\rho^2 \ne 0}} \frac{\slQuad(x)}{\sum_{\rho} x_\rho^{2}}.
\]
Since $Q$ is symmetric positive semidefinite, this equals the largest eigenvalue of $Q$.
\end{definition}

\section{Main results}

\begin{theorem}[\texttt{slQuad\_nonneg}]
For every $x \in \R^R$, $\slQuad(x) \ge 0$.
\end{theorem}
\begin{proof}
Each summand is a square, hence nonnegative; a finite sum of nonnegative reals is nonnegative.
\end{proof}

\begin{theorem}[\texttt{slQuad\_eq\_matrix}]
For every $x \in \R^R$,
\[
\slQuad(x) = \sum_{\rho \in R}\sum_{\rho' \in R} Q_{\rho\rho'}\, x_\rho\, x_{\rho'} = x^{\T} Q\, x.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Expand each squared facet-sum as $\sum_{\rho,\rho'} \mathbf{1}[\rho,\rho'\in\facet(f)]\,x_\rho x_{\rho'}$, sum over $f$, and exchange the finite order of summation; the inner sum over $f$ of the indicator is $Q_{\rho\rho'}$ by definition.
\end{proof}

\begin{theorem}[\texttt{slQuad\_le}]
If $|\facet(f)| \le s$ for all $f$ and $\deg(\rho) \le D$ for all $\rho$, then for every $x \in \R^R$,
\[
\slQuad(x) \le s\,D \sum_{\rho \in R} x_\rho^{2}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
By per-facet Cauchy--Schwarz, $\bigl(\sum_{\rho\in\facet(f)} x_\rho\bigr)^2 \le |\facet(f)|\sum_{\rho\in\facet(f)} x_\rho^2 \le s\sum_{\rho\in\facet(f)} x_\rho^2$. Summing and double-counting ($x_\rho^2$ appears $\deg(\rho)$ times):
\[
\slQuad(x) \le s\sum_{f}\sum_{\rho\in\facet(f)} x_\rho^2 = s\sum_{\rho} \deg(\rho)\,x_\rho^2 \le sD\sum_\rho x_\rho^2. \qedhere
\]
\end{proof}

\begin{theorem}[\texttt{specRad\_le}]
With $s,D$ as above, $\specRad \le sD$. For a pure $r$-complex ($s = r+1$, $\Delta = $ max ridge degree),
\[
q_{r-1}(K) \le (r+1)\,\Delta.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Every Rayleigh quotient is $\le sD$ by the previous theorem; hence so is the supremum.
\end{proof}

\begin{theorem}[\texttt{specRad\_nonneg}]
$\specRad \ge 0$.
\end{theorem}
\begin{proof}
Each Rayleigh quotient is nonnegative (nonnegative numerator, positive denominator); the supremum of a nonempty set of nonnegative reals is nonnegative.
\end{proof}

\begin{theorem}[\texttt{simplex\_specRad}]
For a single $r$-simplex, $q_{r-1}(\text{simplex}) = r+1$, attained by the all-ones vector.
\end{theorem}
\begin{proof}[Proof sketch]
The all-ones vector gives numerator $(r+1)^2$ and denominator $r+1$, so the Rayleigh quotient equals $r+1$ and $\specRad \ge r+1$; the reverse is the spectral bound with $s = r+1$, $\Delta = 1$.
\end{proof}

\section{The graph case and the catalog bridge}

\begin{definition}[edge facets]
For a finite simple graph $G$ on $V$, $\edgeFacet(e) := \{ v \in V : v \in e \} \subseteq V$.
\end{definition}

\begin{lemma}[\texttt{edgeFacet\_card\_two}]
For every edge $e$, $|\edgeFacet(e)| = 2$.
\end{lemma}
\begin{proof}
An edge $e = \{a,b\}$ has distinct endpoints; the filtered set is the pair $\{a,b\}$, of cardinality $2$.
\end{proof}

\begin{theorem}[\texttt{graph\_specRad\_le}]
If every vertex of $G$ lies in at most $D$ edges, then $\specRad(\edgeFacet\,G) \le 2D$. With $D = \Delta(G)$ this is $q(G) \le 2\Delta(G)$.
\end{theorem}
\begin{proof}
Apply the spectral bound with facet size $s = 2$ and degree bound $D$.
\end{proof}

\begin{theorem}[catalog bridge, \texttt{oneSkel\_cliqueComplex\_eq}]
For any graph $G$, $\oneSkel(\cliqueComplex\,G) = G$.
\end{theorem}
\begin{proof}[Proof sketch]
Distinct $a,b$ are adjacent in $\oneSkel(\cliqueComplex\,G)$ iff $\{a,b\}$ is a clique of $G$ (the characterization \texttt{clique\_pair\_iff}), iff $a,b$ adjacent in $G$.
\end{proof}

\begin{remark}[boundary example]
The complete graph $K_3$ as a $1$-complex has each vertex of degree $2$, so $q(K_3) \le 4$; in fact $q(K_3) = 4$. As a $1$-complex $K_3$ has a nontrivial $1$-cycle ($\rH_1 \ne 0$), violating the homology hypothesis, which is exactly why it reaches the ceiling that hole-free complexes respect.
\end{remark}

\section{Reduction of the conjecture}

The conjectured bound matches $(r+1)\Delta$ when $\Delta \le (tn - (t-1)(r+1))/(r+1)$. Hence:

\begin{remark}[reduction]
To prove the conjectured spectral bound it suffices to prove: if $\rH_t(\lk(\sigma);\R) = 0$ for every $(r-t)$-face $\sigma$, then $\deg(\rho) \le (tn - (t-1)(r+1))/(r+1)$ for every ridge $\rho$. The spectral analysis is complete; only a homological degree estimate remains. For the equality case, the all-ones maximizer of \texttt{simplex\_specRad} and facet-wise tightness of Cauchy--Schwarz, propagated by $r$-down-path-connectivity, give the structural rigidity.
\end{remark}

\section{Future directions}

\paragraph{D1. Homology-vanishing $\Rightarrow$ ridge-degree ceiling.} If $\rH_t(\lk(\sigma);\R) = 0$ for every $(r-t)$-face $\sigma$, then $\deg(\rho) \le (tn-(t-1)(r+1))/(r+1)$. Combined with \texttt{specRad\_le} ($s=r+1$) this single degree bound yields the conjectured bound with no further spectral input.

\paragraph{D2. Equality forces a single high-degree star (rigidity).} If $q_{r-1}(K)=(\text{facet size})\cdot(\text{max degree})$, per-facet Cauchy--Schwarz tightness forces the Perron eigenvector constant on every facet; $r$-down-path-connectivity propagates to a global constant (join-of-simplex). \texttt{simplex\_specRad} exhibits the all-ones extremal vector.

\paragraph{D3. Down-Laplacian / Hodge symmetry.} The same bound holds for the down signless Laplacian on $r$-faces, with facet size replaced by the common-coface count. Since \texttt{slQuad\_eq\_matrix} shows the form is $BB^{\T}$, the dual $B^{\T}B$ shares the nonzero spectrum, so a transposed row-sum bound transfers for free.

\paragraph{D4. Strict improvement under positive higher Betti numbers.} If some link has $\rH_t \ne 0$, the spectral radius can exceed $tn-(t-1)(r+1)$, the excess at least the smallest nonzero reduced Betti number of that link. The graph case already gives the violation $q(K_3) = 4 > 3$.

\section{Discussion}

By isolating the signless Laplacian as the sum of squares $\slQuad$ and certifying its identity with $BB^{\T}$, the spectral problem collapses onto a single Cauchy--Schwarz and a double-count, valid in every dimension. The resulting $q_{r-1} \le (r+1)\Delta$ generalizes $q(G)\le 2\Delta$, is sharp on the simplex, and reduces a topological conjecture to combinatorics. The faithful clique-complex bridge anchors the abstraction in classical graph theory, while the unfilled triangle pinpoints the role of homology.

\end{document}

