function EXACT_SPECTRAL_RADIUS(facets):
  R <- sorted set of all ridges occurring in any facet
  index <- map each ridge to a column-free row position
  B <- zero matrix of shape (|R|, |facets|)
  for j, f in enumerate(facets):
    for rho in f: B[index[rho], j] <- 1
  Q <- B * B^T            // Q[rho][rho'] = #facets containing both
  if Q empty: return 0
  return max(eigenvalues_symmetric(Q))

function CERTIFIED_BOUND(facets):
  if facets empty: return 0
  s <- max over f in facets of |f|              // facet size
  R <- set of all ridges
  for rho in R: deg[rho] <- #{ f : rho in f }
  D <- max over rho of deg[rho]                 // max ridge degree
  return s * D                                  // >= q_{r-1}(K)

